/**
 * Embed the QuickJS bootstrap + guest modules for the V8 guest.
 * The C++ kernel has its own copy of the bootstrap inside node_runner.cpp.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const cpp = readFileSync(join(root, 'kernel/src/node_runner.cpp'), 'utf8').replace(/\r\n/g, '\n');
const marker = 'static const char kBootstrap[] = R"JS(\n';
const start = cpp.indexOf(marker);
if (start < 0) throw new Error('kBootstrap not found');
const from = start + marker.length;
const end = cpp.indexOf('\n)JS";', from);
if (end < 0) throw new Error('kBootstrap end not found');
const bootstrap = cpp.slice(from, end);
const modules = readFileSync(join(root, 'kernel/embed/guest_modules.js'), 'utf8').replace(/\r\n/g, '\n');
const out = `/* Generated by scripts/gen-guest-bundle.mjs — do not edit. */\nexport const GUEST_BOOTSTRAP = ${JSON.stringify(bootstrap)};\nexport const GUEST_MODULES = ${JSON.stringify(modules)};\n`;
writeFileSync(join(root, 'packages/api/src/kernel/guest_bundle.ts'), out);
console.log('generated packages/api/src/kernel/guest_bundle.ts', out.length);
